import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-idx-l1-001', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is an index in PostgreSQL?', options: ['A copy of the table', 'A data structure that speeds up data retrieval by providing quick lookup paths', 'A backup mechanism', 'A type of constraint'], correctAnswer: 1, explanation: 'An index is a separate data structure that maintains pointers to rows in the table, allowing the database to find rows without scanning the entire table.', tags: ['index', 'basics', 'definition'] },
  { id: 'pg-idx-l1-002', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is the default index type in PostgreSQL?', options: ['Hash', 'GiST', 'B-tree', 'BRIN'], correctAnswer: 2, explanation: 'B-tree is the default index type. It is suitable for equality and range queries and supports most comparison operators.', tags: ['b-tree', 'default', 'index-type'] },
  { id: 'pg-idx-l1-003', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'CREATE INDEX', question: 'What is the syntax to create an index?', options: ['ADD INDEX ON table(col);', 'CREATE INDEX idx_name ON table(col);', 'NEW INDEX idx_name FOR table(col);', 'INDEX CREATE idx_name ON table(col);'], correctAnswer: 1, explanation: 'CREATE INDEX creates a new index. The index name is optional but recommended for clarity. The column(s) to index are specified in parentheses.', codeSnippet: 'CREATE INDEX idx_users_email ON users (email);', tags: ['create-index', 'syntax', 'basics'] },
  { id: 'pg-idx-l1-004', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Benefits', question: 'What is the main benefit of creating an index on a column?', options: ['Reduces storage space', 'Speeds up queries that filter or sort by that column', 'Prevents NULL values', 'Encrypts the column data'], correctAnswer: 1, explanation: 'Indexes speed up SELECT queries with WHERE, ORDER BY, and JOIN conditions on the indexed column by avoiding full table scans.', tags: ['benefits', 'speed', 'query-optimization'] },
  { id: 'pg-idx-l1-005', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Trade-offs', question: 'What is a downside of having too many indexes on a table?', options: ['Queries become slower', 'INSERT, UPDATE, and DELETE operations become slower because each index must be updated', 'The table data is corrupted', 'No downside at all'], correctAnswer: 1, explanation: 'Each index must be maintained when data changes. More indexes means more work for INSERT/UPDATE/DELETE operations, and more disk space is used.', tags: ['trade-offs', 'write-performance', 'disk-space'] },
  { id: 'pg-idx-l1-006', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Types', question: 'Which queries does a B-tree index support efficiently?', options: ['Only equality (=)', 'Equality and range queries (=, <, >, <=, >=, BETWEEN)', 'Only pattern matching', 'Only full-text search'], correctAnswer: 1, explanation: 'B-tree indexes support equality and range comparisons. They also support ORDER BY (sorted data), IS NULL, and IN operations efficiently.', tags: ['b-tree', 'query-types', 'range'] },
  { id: 'pg-idx-l1-007', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Unique Index', question: 'What does a UNIQUE index enforce?', options: ['Values are sorted', 'All values in the indexed column(s) are distinct', 'Values are not NULL', 'The column has a default value'], correctAnswer: 1, explanation: 'A UNIQUE index ensures no two rows have the same value in the indexed column(s). It is automatically created for PRIMARY KEY and UNIQUE constraints.', codeSnippet: 'CREATE UNIQUE INDEX idx_users_email ON users (email);', tags: ['unique-index', 'constraint', 'distinct'] },
  { id: 'pg-idx-l1-008', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Primary Key', question: 'Does PostgreSQL automatically create an index for a PRIMARY KEY?', options: ['No, you must create it manually', 'Yes, a unique B-tree index is created automatically', 'Only if specified', 'It creates a hash index'], correctAnswer: 1, explanation: 'PostgreSQL automatically creates a unique B-tree index when you define a PRIMARY KEY constraint. The same applies to UNIQUE constraints.', tags: ['primary-key', 'automatic-index', 'unique'] },
  { id: 'pg-idx-l1-009', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'DROP INDEX', question: 'How do you remove an index?', options: ['DELETE INDEX idx_name;', 'REMOVE INDEX idx_name;', 'DROP INDEX idx_name;', 'ALTER TABLE DROP INDEX idx_name;'], correctAnswer: 2, explanation: 'DROP INDEX removes an existing index. Use IF EXISTS to avoid errors if the index does not exist.', codeSnippet: 'DROP INDEX IF EXISTS idx_users_email;', tags: ['drop-index', 'remove', 'ddl'] },
  { id: 'pg-idx-l1-010', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'How do you check if a query uses an index?', options: ['Using SHOW INDEX', 'Using EXPLAIN before the query', 'Using CHECK INDEX', 'Using INDEX STATUS'], correctAnswer: 1, explanation: 'EXPLAIN shows the query plan. If an index is used, you will see "Index Scan" or "Index Only Scan" instead of "Seq Scan" (sequential scan).', codeSnippet: 'EXPLAIN SELECT * FROM users WHERE email = \'test@test.com\';', tags: ['explain', 'query-plan', 'index-scan'] },
  { id: 'pg-idx-l1-011', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does "Seq Scan" in EXPLAIN output mean?', options: ['The query uses a sequence', 'A full table scan — every row is read', 'A sequential index scan', 'A sorted scan'], correctAnswer: 1, explanation: 'Seq Scan (Sequential Scan) means PostgreSQL reads every row in the table. This happens when no suitable index exists or the table is small enough that a full scan is faster.', tags: ['seq-scan', 'full-scan', 'explain'] },
  { id: 'pg-idx-l1-012', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does "Index Scan" in EXPLAIN output mean?', options: ['The index is being rebuilt', 'The query uses an index to find matching rows, then fetches data from the table', 'The table has too many indexes', 'The index is corrupted'], correctAnswer: 1, explanation: 'Index Scan means the query traverses the index to find matching row pointers, then fetches the actual row data from the heap (table).', tags: ['index-scan', 'explain', 'heap-fetch'] },
  { id: 'pg-idx-l1-013', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Composite Index', question: 'What is a composite (multi-column) index?', options: ['An index on multiple tables', 'An index on two or more columns of the same table', 'An index type for JSON', 'An index with multiple algorithms'], correctAnswer: 1, explanation: 'A composite index covers multiple columns. The order of columns matters — the index is most useful for queries that filter on the leading (leftmost) columns.', codeSnippet: 'CREATE INDEX idx_orders_user_date\nON orders (user_id, created_at);', tags: ['composite-index', 'multi-column', 'column-order'] },
  { id: 'pg-idx-l1-014', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Composite Index', question: 'Does the column order matter in a composite index?', options: ['No, order does not matter', 'Yes, the index is most efficient when queries filter on the leftmost columns', 'Only for B-tree indexes', 'Only when there are more than 3 columns'], correctAnswer: 1, explanation: 'B-tree composite indexes are organized left-to-right. An index on (a, b, c) efficiently supports queries filtering on (a), (a, b), or (a, b, c), but not (b) or (c) alone.', tags: ['column-order', 'leading-column', 'composite'] },
  { id: 'pg-idx-l1-015', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Selection', question: 'When should you consider creating an index?', options: ['On every column', 'On columns frequently used in WHERE, JOIN, and ORDER BY clauses', 'Only on the primary key', 'Never — PostgreSQL handles it automatically'], correctAnswer: 1, explanation: 'Create indexes on columns frequently used in WHERE filters, JOIN conditions, and ORDER BY clauses. Avoid indexing columns rarely used in queries or with very low selectivity.', tags: ['when-to-index', 'selection', 'best-practice'] },
  { id: 'pg-idx-l1-016', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Size', question: 'Does an index take up additional disk space?', options: ['No, indexes are stored within the table', 'Yes, indexes are separate data structures that use additional disk space', 'Only temporary space during creation', 'Only if the index is UNIQUE'], correctAnswer: 1, explanation: 'Indexes are stored separately from the table data. They can be substantial in size, sometimes as large as the table itself for large indexes.', tags: ['disk-space', 'storage', 'overhead'] },
  { id: 'pg-idx-l1-017', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN ANALYZE', question: 'What additional information does EXPLAIN ANALYZE provide over EXPLAIN?', options: ['Index suggestions', 'Actual execution times and row counts from running the query', 'Table statistics', 'Index health information'], correctAnswer: 1, explanation: 'EXPLAIN ANALYZE actually runs the query and shows real timing and row counts alongside the planned estimates, helping identify where estimates are wrong.', codeSnippet: 'EXPLAIN ANALYZE\nSELECT * FROM users WHERE age > 25;', tags: ['explain-analyze', 'actual-timing', 'row-counts'] },
  { id: 'pg-idx-l1-018', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'When Index Not Used', question: 'Why might PostgreSQL choose not to use an index?', options: ['The index is broken', 'The table is small enough that a sequential scan is faster, or the query returns most of the table', 'PostgreSQL does not support index usage', 'Only UNIQUE indexes are used'], correctAnswer: 1, explanation: 'The planner estimates whether an index scan is cheaper than a sequential scan. For small tables or queries returning a large fraction of rows, a sequential scan may be faster.', tags: ['index-not-used', 'planner-decision', 'selectivity'] },
  { id: 'pg-idx-l1-019', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Hash Index', question: 'What is a Hash index best for?', options: ['Range queries', 'Simple equality comparisons (=) only', 'Pattern matching', 'Sorting'], correctAnswer: 1, explanation: 'Hash indexes only support equality (=) lookups. They cannot be used for range queries, sorting, or partial matching. B-tree indexes are more versatile.', codeSnippet: 'CREATE INDEX idx_users_email_hash\nON users USING hash (email);', tags: ['hash-index', 'equality', 'limitations'] },
  { id: 'pg-idx-l1-020', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Partial Index', question: 'What is a partial index?', options: ['An index on part of a column', 'An index that covers only a subset of rows, defined by a WHERE clause', 'An incomplete index', 'An index on the first few characters'], correctAnswer: 1, explanation: 'A partial index indexes only rows that satisfy a WHERE condition. This makes the index smaller and more efficient for queries that match the condition.', codeSnippet: 'CREATE INDEX idx_active_users\nON users (email)\nWHERE active = true;', tags: ['partial-index', 'where-clause', 'filtered'] },
  { id: 'pg-idx-l1-021', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Expression Index', question: 'What is an expression (functional) index?', options: ['An index on a table expression', 'An index on the result of a function or expression applied to a column', 'A mathematical index', 'An index with conditions'], correctAnswer: 1, explanation: 'An expression index indexes the result of an expression. Useful for queries that filter on function results, like LOWER(email) for case-insensitive searches.', codeSnippet: 'CREATE INDEX idx_users_lower_email\nON users (LOWER(email));', tags: ['expression-index', 'functional', 'lower'] },
  { id: 'pg-idx-l1-022', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Only Scan', question: 'What is an "Index Only Scan"?', options: ['A scan that only creates indexes', 'A scan that retrieves all needed data from the index itself without accessing the table', 'A scan of the index metadata', 'A scan that only uses the primary index'], correctAnswer: 1, explanation: 'When all columns needed by a query are in the index, PostgreSQL can read data directly from the index without visiting the heap table, which is much faster.', tags: ['index-only-scan', 'covering', 'performance'] },
  { id: 'pg-idx-l1-023', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Covering Index', question: 'What is a covering index?', options: ['An index that covers the whole table', 'An index that includes all columns needed by a query, enabling Index Only Scans', 'An index with full coverage', 'An index on all columns'], correctAnswer: 1, explanation: 'A covering index includes all columns referenced by a query (in SELECT, WHERE, etc.), allowing the query to be answered entirely from the index.', codeSnippet: 'CREATE INDEX idx_covering\nON orders (user_id) INCLUDE (total, status);', tags: ['covering-index', 'include', 'index-only'] },
  { id: 'pg-idx-l1-024', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'INCLUDE', question: 'What does the INCLUDE clause do in CREATE INDEX?', options: ['Includes the index in backups', 'Adds non-key columns to the index for covering index purposes without affecting the search tree structure', 'Includes NULL values', 'Includes other indexes'], correctAnswer: 1, explanation: 'INCLUDE adds columns to the index leaf pages without making them part of the search key. This enables Index Only Scans without affecting index key ordering.', codeSnippet: 'CREATE INDEX idx_users_email_incl\nON users (email) INCLUDE (name, created_at);', tags: ['include', 'non-key-columns', 'covering'] },
  { id: 'pg-idx-l1-025', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Foreign Key Index', question: 'Does PostgreSQL automatically create an index on foreign key columns?', options: ['Yes, always', 'No, you should create indexes on foreign key columns manually', 'Only for cascading deletes', 'Only if the referenced table has an index'], correctAnswer: 1, explanation: 'Unlike some databases, PostgreSQL does NOT automatically index foreign key columns. You should manually create indexes on FK columns to speed up joins and cascading operations.', tags: ['foreign-key', 'no-auto-index', 'manual'] },
  { id: 'pg-idx-l1-026', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'REINDEX', question: 'What does REINDEX do?', options: ['Creates a new index', 'Rebuilds an existing index from scratch to fix corruption or reduce bloat', 'Renames an index', 'Removes an index'], correctAnswer: 1, explanation: 'REINDEX rebuilds one or more indexes. Useful for fixing index corruption, reducing bloat, or after changing index parameters.', codeSnippet: 'REINDEX INDEX idx_users_email;\nREINDEX TABLE users;', tags: ['reindex', 'rebuild', 'maintenance'] },
  { id: 'pg-idx-l1-027', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Bitmap Index Scan', question: 'What is a Bitmap Index Scan?', options: ['A scan using bitmap images', 'A two-phase scan that first builds a bitmap of matching pages, then reads those pages from the table', 'A scan of BOOLEAN columns', 'A compressed index scan'], correctAnswer: 1, explanation: 'Bitmap Index Scan builds a bitmap of heap pages containing matching rows, then reads those pages. It is efficient for medium-selectivity queries and can combine multiple indexes.', tags: ['bitmap-scan', 'two-phase', 'medium-selectivity'] },
  { id: 'pg-idx-l1-028', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'GIN Index', question: 'What are GIN indexes primarily used for?', options: ['Geographic data', 'Full-text search, arrays, and JSONB — data types with multiple values per row', 'Integer columns', 'Date ranges'], correctAnswer: 1, explanation: 'GIN (Generalized Inverted Index) is ideal for indexing composite values like arrays, JSONB, and tsvector (full-text search). It maps each element to the rows containing it.', codeSnippet: 'CREATE INDEX idx_posts_tags ON posts USING gin (tags);\nCREATE INDEX idx_docs_search ON docs USING gin (to_tsvector(\'english\', content));', tags: ['gin', 'full-text', 'jsonb'] },
  { id: 'pg-idx-l1-029', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'GiST Index', question: 'What are GiST indexes commonly used for?', options: ['Text search only', 'Geometric, range, and full-text search data — supporting complex operators like overlap and containment', 'Only for B-tree fallback', 'Integer sorting'], correctAnswer: 1, explanation: 'GiST (Generalized Search Tree) supports geometric types, range types, full-text search, and nearest-neighbor queries. It is essential for PostGIS spatial queries.', codeSnippet: 'CREATE INDEX idx_locations ON places USING gist (coordinates);', tags: ['gist', 'geometric', 'range-types'] },
  { id: 'pg-idx-l1-030', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'BRIN Index', question: 'What is a BRIN index best suited for?', options: ['Small tables', 'Large tables where data is physically ordered (e.g., time-series data with sequential inserts)', 'All table types', 'Only text columns'], correctAnswer: 1, explanation: 'BRIN (Block Range Index) stores summary information per range of physical pages. It is very compact and efficient for naturally ordered data like timestamps.', codeSnippet: 'CREATE INDEX idx_logs_time ON logs USING brin (created_at);', tags: ['brin', 'block-range', 'time-series'] },
  { id: 'pg-idx-l1-031', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'CONCURRENTLY', question: 'What does CREATE INDEX CONCURRENTLY do?', options: ['Creates the index faster', 'Creates the index without blocking writes to the table', 'Creates multiple indexes at once', 'Creates a concurrent access index'], correctAnswer: 1, explanation: 'Regular CREATE INDEX blocks writes. CONCURRENTLY allows inserts, updates, and deletes to continue during index creation, at the cost of longer build time.', codeSnippet: 'CREATE INDEX CONCURRENTLY idx_users_email\nON users (email);', tags: ['concurrently', 'non-blocking', 'online'] },
  { id: 'pg-idx-l1-032', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Usage', question: 'How can you check which indexes exist on a table in psql?', options: ['SHOW INDEXES FROM table;', '\\di table_name or \\d table_name', 'LIST INDEXES ON table;', 'SELECT * FROM indexes;'], correctAnswer: 1, explanation: '\\di lists indexes. \\d table_name shows the table structure including all indexes. You can also query pg_indexes system catalog.', tags: ['psql', 'list-indexes', 'meta-commands'] },
  { id: 'pg-idx-l1-033', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What happens to indexes when you INSERT a new row?', options: ['Nothing — indexes are static', 'All indexes on the table are updated to include the new row', 'Only the primary key index is updated', 'Indexes are updated lazily'], correctAnswer: 1, explanation: 'When a row is inserted, every index on the table must be updated to include the new row. This is why having many indexes slows down INSERT operations.', tags: ['insert', 'index-maintenance', 'overhead'] },
  { id: 'pg-idx-l1-034', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'LIKE Queries', question: 'Can a B-tree index speed up LIKE queries?', options: ['No, never', 'Yes, but only for prefix patterns like \'abc%\', not \'%abc\' or \'%abc%\'', 'Yes, for all LIKE patterns', 'Only with GIN indexes'], correctAnswer: 1, explanation: 'B-tree indexes can optimize prefix LIKE patterns (LIKE \'abc%\') because they are equivalent to a range query. Suffix or infix patterns require GIN with pg_trgm.', codeSnippet: '-- This CAN use a B-tree index:\nSELECT * FROM users WHERE name LIKE \'John%\';\n\n-- This CANNOT:\nSELECT * FROM users WHERE name LIKE \'%John%\';', tags: ['like', 'prefix', 'pattern-matching'] },
  { id: 'pg-idx-l1-035', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'NULL and Indexes', question: 'Can NULL values be indexed in PostgreSQL?', options: ['No, NULLs are never indexed', 'Yes, B-tree indexes include NULL values', 'Only with partial indexes', 'Only with GiST indexes'], correctAnswer: 1, explanation: 'PostgreSQL B-tree indexes include NULL values. This allows efficient IS NULL and IS NOT NULL queries and means NULLs are stored in the index.', tags: ['null', 'indexed', 'b-tree'] },
  { id: 'pg-idx-l1-036', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Scan Direction', question: 'Can a B-tree index be scanned in both directions?', options: ['No, only ascending', 'Yes, B-tree indexes can be scanned forward (ASC) or backward (DESC)', 'Only with DESC keyword in CREATE INDEX', 'Only for numeric columns'], correctAnswer: 1, explanation: 'B-tree indexes are doubly-linked, so they can be scanned in both directions. An index on (col ASC) can also satisfy ORDER BY col DESC queries.', tags: ['scan-direction', 'asc-desc', 'bidirectional'] },
  { id: 'pg-idx-l1-037', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index vs Table', question: 'What is the relationship between an index and the table data?', options: ['The index contains all table data', 'The index stores column values and pointers (ctids) to the actual table rows', 'The index replaces the table', 'They are the same structure'], correctAnswer: 1, explanation: 'An index stores the indexed column values along with ctid (physical row location) pointers. To get non-indexed columns, PostgreSQL must "visit" the heap table.', tags: ['index-structure', 'ctid', 'heap-pointer'] },
  { id: 'pg-idx-l1-038', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the main advantage of Index Only Scan over Index Scan?', options: ['It uses less CPU', 'It avoids the extra step of fetching data from the table (heap), reducing I/O', 'It works on more data types', 'It is always used'], correctAnswer: 1, explanation: 'Index Only Scan does not need to access the heap table because all needed data is in the index. This significantly reduces disk I/O, especially for wide tables.', tags: ['index-only-scan', 'heap-access', 'io-reduction'] },
  { id: 'pg-idx-l1-039', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Selection', question: 'Should you create an index on a column with very few distinct values (like a boolean)?', options: ['Yes, always', 'Usually not — low selectivity means the index would match too many rows to be useful', 'Only for UNIQUE indexes', 'Only if the table is small'], correctAnswer: 1, explanation: 'An index on a boolean column (or any low-cardinality column) is usually not helpful because each value matches 50% of rows. A partial index on the rare value can be useful though.', codeSnippet: '-- Not useful: index on boolean\nCREATE INDEX idx_active ON users (active);\n\n-- Useful: partial index for rare condition\nCREATE INDEX idx_active_only ON users (id)\nWHERE active = true;', tags: ['selectivity', 'low-cardinality', 'partial-index'] },
  { id: 'pg-idx-l1-040', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Maintenance', question: 'What is index bloat?', options: ['An index that is too large to fit in memory', 'Wasted space in the index caused by updates and deletes leaving dead entries', 'An index with too many columns', 'A corrupted index'], correctAnswer: 1, explanation: 'As rows are updated and deleted, dead entries remain in the index. Over time, this wasted space (bloat) makes the index larger and slower. VACUUM and REINDEX help manage bloat.', tags: ['bloat', 'dead-entries', 'maintenance'] },
  { id: 'pg-idx-l1-041', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Query Optimization', question: 'What does ANALYZE do for query performance?', options: ['Runs the query faster', 'Updates table statistics so the query planner can make better decisions about using indexes', 'Analyzes index structure', 'Optimizes the index layout'], correctAnswer: 1, explanation: 'ANALYZE collects statistics about column value distribution. The planner uses these statistics to decide whether to use an index, which join strategy to pick, etc.', codeSnippet: 'ANALYZE users;  -- Update statistics for the users table', tags: ['analyze', 'statistics', 'planner'] },
  { id: 'pg-idx-l1-042', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Types', question: 'Which index type should you use for full-text search?', options: ['B-tree', 'Hash', 'GIN or GiST', 'BRIN'], correctAnswer: 2, explanation: 'GIN is the most common choice for full-text search (tsvector columns). GiST also supports full-text search with different trade-offs (smaller, slower, but supports ranking distance).', tags: ['full-text-search', 'gin', 'gist'] },
  { id: 'pg-idx-l1-043', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'ORDER BY', question: 'How can an index help with ORDER BY?', options: ['Indexes do not help with sorting', 'An index on the ORDER BY column provides pre-sorted data, avoiding a separate sort step', 'Only for ASC order', 'Only with LIMIT'], correctAnswer: 1, explanation: 'If an index matches the ORDER BY column(s) and direction, PostgreSQL can read data in sorted order directly from the index, eliminating the need for a sort operation.', tags: ['order-by', 'pre-sorted', 'sort-elimination'] },
  { id: 'pg-idx-l1-044', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does the "cost" in EXPLAIN output represent?', options: ['Dollar cost', 'An estimate of the work required in arbitrary units (startup_cost..total_cost)', 'Execution time in seconds', 'Number of rows'], correctAnswer: 1, explanation: 'Cost is expressed in arbitrary units representing estimated I/O and CPU work. The format is startup_cost..total_cost. Lower is generally better, but absolute values are not comparable across different systems.', tags: ['explain', 'cost', 'units'] },
  { id: 'pg-idx-l1-045', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'pg_trgm', question: 'What extension helps with fuzzy text search and LIKE \'%pattern%\' queries?', options: ['pg_search', 'pg_trgm', 'pg_fuzzy', 'pg_text'], correctAnswer: 1, explanation: 'pg_trgm (trigram) extension enables GIN/GiST indexes that support LIKE \'%pattern%\', ILIKE, and similarity matching. Essential for search functionality.', codeSnippet: 'CREATE EXTENSION pg_trgm;\nCREATE INDEX idx_name_trgm ON users USING gin (name gin_trgm_ops);', tags: ['pg-trgm', 'trigram', 'fuzzy-search'] },
  { id: 'pg-idx-l1-046', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Selection', question: 'What is the "selectivity" of an index?', options: ['How fast the index is', 'The fraction of rows an index condition matches — lower is more selective and better', 'The number of columns indexed', 'The index size'], correctAnswer: 1, explanation: 'Selectivity is the percentage of rows matching a condition. An email lookup (0.001%) is highly selective. A boolean flag (50%) is not. High selectivity makes indexes more useful.', tags: ['selectivity', 'fraction', 'effectiveness'] },
  { id: 'pg-idx-l1-047', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'Can a table have multiple indexes?', options: ['No, only one index per table', 'Yes, a table can have many indexes on different columns or combinations', 'Only up to 5', 'Only if they are different types'], correctAnswer: 1, explanation: 'A table can have multiple indexes. Each serves different query patterns. However, too many indexes slow down writes and consume disk space.', tags: ['multiple-indexes', 'table', 'limit'] },
  { id: 'pg-idx-l1-048', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the difference between a sequential scan and an index scan in terms of speed?', options: ['Sequential scan is always faster', 'Index scan is faster for selective queries; sequential scan is faster for large result sets', 'They are always the same speed', 'Index scan is always faster'], correctAnswer: 1, explanation: 'Index scan excels at finding a small number of rows. Sequential scan is faster when reading most of the table because it reads pages in order (sequential I/O is faster than random I/O).', tags: ['seq-scan', 'index-scan', 'comparison'] },
  { id: 'pg-idx-l1-049', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does "rows" in EXPLAIN output represent?', options: ['Total table rows', 'The estimated number of rows the plan node will output', 'Number of indexed rows', 'Rows per page'], correctAnswer: 1, explanation: 'The "rows" value is the planner\'s estimate of how many rows this plan node will produce. EXPLAIN ANALYZE shows both the estimate and the actual count.', tags: ['explain', 'rows-estimate', 'plan-node'] },
  { id: 'pg-idx-l1-050', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is an index scan "filter"?', options: ['A hardware filter', 'A condition checked on rows retrieved by the index that could not be checked by the index itself', 'A way to filter indexes', 'An index type'], correctAnswer: 1, explanation: 'After the index returns rows, additional WHERE conditions that are not part of the index key are checked as "filters". High filter removal counts suggest the index could be more targeted.', tags: ['filter', 'index-scan', 'additional-conditions'] },
  { id: 'pg-idx-l1-051', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Types', question: 'What is the key advantage of BRIN indexes over B-tree indexes?', options: ['BRIN is faster for all queries', 'BRIN indexes are much smaller (often 1000x) because they store summaries per block range, not per row', 'BRIN supports more operators', 'BRIN indexes are always used'], correctAnswer: 1, explanation: 'BRIN indexes are extremely compact because they store min/max values per range of physical pages. They are ideal for large append-only tables where data is physically ordered.', tags: ['brin', 'compact', 'block-range'] },
  { id: 'pg-idx-l1-052', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the pg_stat_user_indexes view used for?', options: ['Creating indexes', 'Monitoring index usage: how often each index is scanned', 'Listing all index types', 'Showing index sizes'], correctAnswer: 1, explanation: 'pg_stat_user_indexes shows how often each index is used (idx_scan count), how many tuples are read/fetched. Low usage may indicate unused indexes that could be dropped.', codeSnippet: 'SELECT indexrelname, idx_scan, idx_tup_read\nFROM pg_stat_user_indexes\nWHERE schemaname = \'public\'\nORDER BY idx_scan;', tags: ['pg-stat-user-indexes', 'monitoring', 'usage'] },
  { id: 'pg-idx-l1-053', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Unused Indexes', question: 'Why should you drop unused indexes?', options: ['They are security risks', 'They waste disk space, slow down writes, and increase VACUUM workload', 'They cause query errors', 'They prevent table modifications'], correctAnswer: 1, explanation: 'Unused indexes provide no query benefit but still impose costs: disk space, write overhead for every INSERT/UPDATE/DELETE, and additional VACUUM work.', tags: ['unused-indexes', 'cleanup', 'performance'] },
  { id: 'pg-idx-l1-054', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is the purpose of the INCLUDE clause in a UNIQUE index?', options: ['To include more uniqueness columns', 'To store additional columns in the index for covering queries without making them part of the uniqueness check', 'To include NULL values', 'To include foreign keys'], correctAnswer: 1, explanation: 'INCLUDE columns are stored in the index but not part of the unique key. This enables Index Only Scans on UNIQUE indexes while maintaining the original uniqueness constraint.', tags: ['include', 'unique-index', 'covering'] },
  { id: 'pg-idx-l1-055', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Multicolumn', question: 'If you have an index on (a, b, c), which queries can efficiently use it?', options: ['Only WHERE a = 1 AND b = 2 AND c = 3', 'WHERE a = 1, WHERE a = 1 AND b = 2, WHERE a = 1 AND b = 2 AND c = 3', 'Any combination of a, b, c', 'Only WHERE c = 3'], correctAnswer: 1, explanation: 'A B-tree multicolumn index follows the leftmost prefix rule. It efficiently supports queries starting with the leftmost column(s): (a), (a, b), (a, b, c).', tags: ['composite', 'leftmost-prefix', 'usage'] },
  { id: 'pg-idx-l1-056', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Types', question: 'Which index type would you use for a JSONB column?', options: ['B-tree', 'Hash', 'GIN', 'BRIN'], correctAnswer: 2, explanation: 'GIN indexes on JSONB columns support operators like @>, ?, ?&, ?|. They index all keys and values in the JSON document for efficient lookups.', codeSnippet: 'CREATE INDEX idx_data_gin ON documents USING gin (data);', tags: ['gin', 'jsonb', 'operators'] },
  { id: 'pg-idx-l1-057', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What does VACUUM do for indexes?', options: ['Rebuilds all indexes', 'Cleans up dead index entries pointing to removed rows, preventing bloat', 'Creates new indexes', 'Drops unused indexes'], correctAnswer: 1, explanation: 'VACUUM removes dead tuple entries from indexes and marks space as reusable. Regular vacuuming prevents index bloat and maintains query performance.', tags: ['vacuum', 'dead-entries', 'index-maintenance'] },
  { id: 'pg-idx-l1-058', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Selection', question: 'What is the role of the query planner in index selection?', options: ['It always uses the newest index', 'It estimates the cost of different access paths and chooses the cheapest one', 'It randomly selects an index', 'It uses all available indexes'], correctAnswer: 1, explanation: 'The query planner evaluates multiple execution strategies (seq scan, various index scans) and picks the one with the lowest estimated cost based on table statistics.', tags: ['query-planner', 'cost-estimation', 'access-path'] },
  { id: 'pg-idx-l1-059', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'Can you create an index on a view?', options: ['Yes, directly', 'No, but you can create indexes on the underlying tables or on materialized views', 'Only on simple views', 'Only with UNIQUE indexes'], correctAnswer: 1, explanation: 'Regular views do not store data, so they cannot have indexes. Materialized views store data and can be indexed. For regular views, index the underlying tables.', tags: ['view', 'materialized-view', 'indexing'] },
  { id: 'pg-idx-l1-060', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is the pg_indexes system catalog?', options: ['A list of all index types', 'A view showing all indexes in the database with their definitions', 'An index management tool', 'A monitoring dashboard'], correctAnswer: 1, explanation: 'pg_indexes is a system view that shows all indexes: their names, the table they belong to, the column(s), and the full CREATE INDEX statement.', codeSnippet: 'SELECT tablename, indexname, indexdef\nFROM pg_indexes\nWHERE schemaname = \'public\';', tags: ['pg-indexes', 'system-catalog', 'definitions'] },
  { id: 'pg-idx-l1-061', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is a "sequential I/O" vs "random I/O" and why does it matter for indexes?', options: ['They are the same', 'Sequential reads consecutive disk blocks (fast); random reads scattered blocks (slower). Index scans cause random I/O', 'Random I/O is faster', 'Only SSDs care about this'], correctAnswer: 1, explanation: 'Sequential I/O reads consecutive blocks (fast). Index scans jump between scattered pages (random I/O). On spinning disks, random I/O is 100x slower. SSDs reduce this gap.', tags: ['sequential-io', 'random-io', 'disk'] },
  { id: 'pg-idx-l1-062', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'DESC Index', question: 'Can you create an index that is sorted in descending order?', options: ['No, indexes are always ascending', 'Yes, using DESC in the column specification', 'Only for numeric columns', 'Only with B-tree'], correctAnswer: 1, explanation: 'You can specify ASC or DESC for each column in a B-tree index. This is useful for queries that ORDER BY col DESC to avoid a reverse scan.', codeSnippet: 'CREATE INDEX idx_orders_date_desc\nON orders (created_at DESC);', tags: ['desc', 'sort-order', 'index-direction'] },
  { id: 'pg-idx-l1-063', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'NULLS FIRST/LAST', question: 'What does NULLS FIRST do in an index definition?', options: ['Excludes NULL values', 'Places NULL values at the beginning of the index sort order', 'Makes NULLs required', 'Counts NULL values first'], correctAnswer: 1, explanation: 'NULLS FIRST/LAST in the index definition controls where NULLs are placed in the sort order, matching the ORDER BY NULLS FIRST/LAST clause in queries.', codeSnippet: 'CREATE INDEX idx_score ON students (score DESC NULLS LAST);', tags: ['nulls-first', 'nulls-last', 'sort-order'] },
  { id: 'pg-idx-l1-064', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Size', question: 'How can you check the size of an index?', options: ['SHOW INDEX SIZE', 'Using pg_relation_size() or pg_size_pretty(pg_indexes_size())', 'INDEX SIZE command', '\\di+ in psql shows size information'], correctAnswer: 3, explanation: '\\di+ in psql shows index sizes. You can also use pg_relation_size(\'index_name\') or pg_size_pretty(pg_indexes_size(\'table_name\')) for all indexes on a table.', codeSnippet: 'SELECT pg_size_pretty(pg_relation_size(\'idx_users_email\')) AS index_size;\nSELECT pg_size_pretty(pg_indexes_size(\'users\')) AS all_indexes_size;', tags: ['index-size', 'pg-relation-size', 'monitoring'] },
  { id: 'pg-idx-l1-065', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is an "access method" in PostgreSQL?', options: ['A method for accessing the database', 'The algorithm/data structure used to organize index data (B-tree, Hash, GIN, GiST, BRIN)', 'A user access control method', 'A connection method'], correctAnswer: 1, explanation: 'An access method defines the data structure and algorithms for an index type. PostgreSQL has built-in methods (B-tree, Hash, GIN, GiST, BRIN, SP-GiST) and supports custom ones.', tags: ['access-method', 'algorithm', 'data-structure'] },
  { id: 'pg-idx-l1-066', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the benefit of keeping indexes in the PostgreSQL shared buffer cache?', options: ['No benefit', 'Frequently accessed index pages stay in memory, avoiding disk I/O for repeated lookups', 'Indexes are always in cache', 'Cache only helps table data'], correctAnswer: 1, explanation: 'When index pages are in shared_buffers, index lookups avoid disk reads. The more frequently an index is used, the more likely its pages stay cached, improving performance.', tags: ['shared-buffers', 'cache', 'memory'] },
  { id: 'pg-idx-l1-067', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'SP-GiST', question: 'What is SP-GiST?', options: ['A spatial GiST variant', 'Space-Partitioned GiST: an index for data that can be partitioned into non-overlapping regions (like quad-trees)', 'A special GiST mode', 'GiST with spill pages'], correctAnswer: 1, explanation: 'SP-GiST supports partitioned search trees like quad-trees and k-d trees. Useful for point data, IP addresses, and other naturally partitionable data.', tags: ['sp-gist', 'space-partitioned', 'quad-tree'] },
  { id: 'pg-idx-l1-068', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does "width" in EXPLAIN output tell you?', options: ['Table width in bytes', 'The estimated average width (in bytes) of each output row from a plan node', 'Screen display width', 'Index key width'], correctAnswer: 1, explanation: 'Width is the estimated average row size in bytes. Large widths in join outputs indicate wide rows, which consume more memory and I/O.', tags: ['explain', 'width', 'row-size'] },
  { id: 'pg-idx-l1-069', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Autovacuum', question: 'How does autovacuum relate to index performance?', options: ['No relation', 'Autovacuum cleans dead tuples and updates statistics, keeping indexes compact and planner estimates accurate', 'Autovacuum rebuilds indexes', 'Autovacuum creates new indexes'], correctAnswer: 1, explanation: 'Autovacuum removes dead entries from indexes, preventing bloat. It also runs ANALYZE to update statistics, ensuring the planner makes good index usage decisions.', tags: ['autovacuum', 'dead-tuples', 'statistics'] },
  { id: 'pg-idx-l1-070', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Query Performance', question: 'What is the simplest way to improve a slow query?', options: ['Buy faster hardware', 'Check EXPLAIN for Seq Scan on large tables and add indexes on the filtered columns', 'Restart the database', 'Increase connection limit'], correctAnswer: 1, explanation: 'The first step is EXPLAIN (ANALYZE) to see the query plan. If a large table has a Seq Scan and a selective WHERE condition, adding an index on the WHERE column usually helps dramatically.', tags: ['slow-query', 'first-step', 'explain'] },
  { id: 'pg-idx-l1-071', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is a "heap" in PostgreSQL terminology?', options: ['A priority queue', 'The main table storage where actual row data is stored (unordered)', 'A type of index', 'Memory allocation'], correctAnswer: 1, explanation: 'The heap is the main table storage where rows are stored in insertion order (not sorted). Indexes point to rows in the heap using ctid (page number + offset).', tags: ['heap', 'table-storage', 'unordered'] },
  { id: 'pg-idx-l1-072', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'Why is an index on a timestamp column useful for time-range queries?', options: ['Timestamps need special indexes', 'B-tree on timestamp efficiently supports BETWEEN, >, < operators for filtering date ranges', 'Only BRIN works for timestamps', 'Timestamps cannot be indexed'], correctAnswer: 1, explanation: 'B-tree indexes on timestamp columns enable efficient range queries (WHERE created_at BETWEEN \'2024-01-01\' AND \'2024-12-31\') without scanning the entire table.', tags: ['timestamp', 'range-query', 'b-tree'] },
  { id: 'pg-idx-l1-073', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does "Bitmap Heap Scan" mean in EXPLAIN output?', options: ['Scanning the heap in order', 'The second phase of a bitmap scan: reading the heap pages identified by the bitmap index scan', 'A bitmap of the heap', 'A heap-based bitmap'], correctAnswer: 1, explanation: 'Bitmap Heap Scan reads the actual table pages identified by the preceding Bitmap Index Scan. It reads pages in physical order, reducing random I/O.', tags: ['bitmap-heap-scan', 'explain', 'two-phase'] },
  { id: 'pg-idx-l1-074', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Bitmap Scan', question: 'When does PostgreSQL use a Bitmap Scan instead of a regular Index Scan?', options: ['Always for large tables', 'When the query is somewhat selective but returns too many rows for efficient random I/O via regular index scan', 'Never — bitmap scans are legacy', 'Only for GIN indexes'], correctAnswer: 1, explanation: 'Bitmap scans are used for medium selectivity (too many rows for efficient index scan, too few for seq scan). They also combine results from multiple indexes (BitmapAnd/BitmapOr).', tags: ['bitmap-scan', 'medium-selectivity', 'combined-indexes'] },
  { id: 'pg-idx-l1-075', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Composite Index', question: 'What is the "leading column" of a composite index?', options: ['The last column', 'The first (leftmost) column in the index definition', 'The most important column', 'The column with the most unique values'], correctAnswer: 1, explanation: 'The leading column is the first column listed in the index definition. The index is most useful for queries that filter on this column (or this column plus subsequent ones).', tags: ['leading-column', 'composite', 'leftmost'] },
  { id: 'pg-idx-l1-076', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Naming', question: 'Is there a naming convention for indexes in PostgreSQL?', options: ['No, any name works', 'Yes, a common convention is idx_tablename_columnname', 'Names are auto-generated only', 'Only single-character names'], correctAnswer: 1, explanation: 'While not enforced, idx_tablename_columnname is a widely used convention. Clear names help identify what an index covers when debugging or managing indexes.', tags: ['naming', 'convention', 'best-practice'] },
  { id: 'pg-idx-l1-077', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'How do you read EXPLAIN output — what is the "tree" structure?', options: ['A random list of operations', 'A nested tree where child nodes feed data to their parent nodes; data flows from bottom to top', 'A flat list from top to bottom', 'A graph with multiple entry points'], correctAnswer: 1, explanation: 'EXPLAIN output is a tree. Leaf nodes (bottom) scan tables/indexes. Results flow up through join/sort/aggregate nodes to the root (top) which returns the final result.', tags: ['explain', 'tree-structure', 'reading'] },
  { id: 'pg-idx-l1-078', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What does pg_size_pretty() do?', options: ['Makes tables pretty', 'Converts byte sizes to human-readable format (KB, MB, GB)', 'Formats query output', 'Prettifies SQL code'], correctAnswer: 1, explanation: 'pg_size_pretty() converts raw byte counts to human-readable strings. Use it with pg_relation_size(), pg_table_size(), pg_total_relation_size(), etc.', codeSnippet: 'SELECT pg_size_pretty(pg_total_relation_size(\'users\'));', tags: ['pg-size-pretty', 'formatting', 'monitoring'] },
  { id: 'pg-idx-l1-079', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Basics', question: 'What is the difference between pg_table_size() and pg_total_relation_size()?', options: ['No difference', 'pg_table_size includes TOAST but not indexes; pg_total_relation_size includes everything (table + TOAST + indexes)', 'pg_total_relation_size excludes TOAST', 'pg_table_size includes indexes'], correctAnswer: 1, explanation: 'pg_table_size() = heap + TOAST + free space map. pg_total_relation_size() = pg_table_size() + all indexes. Use the latter for the complete disk footprint.', tags: ['table-size', 'total-size', 'disk-usage'] },
  { id: 'pg-idx-l1-080', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Query Performance', question: 'What is a "slow query log" and how do you enable it in PostgreSQL?', options: ['A built-in dashboard', 'Set log_min_duration_statement to log queries exceeding a time threshold', 'A separate monitoring tool', 'It is enabled by default'], correctAnswer: 1, explanation: 'Set log_min_duration_statement to a value in milliseconds (e.g., 1000 = 1 second). All queries taking longer are logged. -1 disables, 0 logs all queries.', codeSnippet: 'SET log_min_duration_statement = \'500ms\';', tags: ['slow-query-log', 'logging', 'configuration'] },
  { id: 'pg-idx-l1-081', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is connection pooling and why does it help performance?', options: ['Pooling database connections in a swimming pool', 'Reusing database connections instead of creating new ones for each request, reducing connection overhead', 'Pooling query results', 'Combining multiple databases'], correctAnswer: 1, explanation: 'Each PostgreSQL connection uses ~10MB+ of memory. Connection poolers (like PgBouncer) reuse connections, supporting many application clients with fewer database connections.', tags: ['connection-pooling', 'pgbouncer', 'memory'] },
  { id: 'pg-idx-l1-082', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Index Types', question: 'Can you combine results from multiple indexes in a single query?', options: ['No, only one index per query', 'Yes, using BitmapAnd and BitmapOr to combine bitmap scans from multiple indexes', 'Only with INTERSECT', 'Only with composite indexes'], correctAnswer: 1, explanation: 'PostgreSQL can combine multiple bitmap index scans using BitmapAnd (for AND conditions) and BitmapOr (for OR conditions), effectively using multiple indexes.', tags: ['bitmap-and-or', 'combined', 'multiple-indexes'] },
  { id: 'pg-idx-l1-083', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the shared_buffers setting?', options: ['Shared disk space', 'The amount of memory PostgreSQL uses for caching data pages (including index pages)', 'Buffer for shared connections', 'Temporary file space'], correctAnswer: 1, explanation: 'shared_buffers is PostgreSQL\'s main cache for data and index pages. It is typically set to 25% of system RAM. Larger values allow more data to be cached in memory.', tags: ['shared-buffers', 'memory', 'cache'] },
  { id: 'pg-idx-l1-084', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the work_mem setting?', options: ['Total system memory', 'Memory available per sort or hash operation — affects query performance for sorts, joins, and aggregation', 'Memory for workers', 'Disk space for temp files'], correctAnswer: 1, explanation: 'work_mem is allocated per sort/hash operation (not per query). Setting it too low causes disk spilling. Setting it too high with many concurrent queries can exhaust memory.', codeSnippet: 'SET work_mem = \'256MB\'; -- Per operation, not per query', tags: ['work-mem', 'sort-memory', 'hash-memory'] },
  { id: 'pg-idx-l1-085', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'EXPLAIN', question: 'What does EXPLAIN (FORMAT YAML) do?', options: ['Exports the query as YAML', 'Shows the query plan in YAML format for machine parsing', 'Creates a YAML index', 'Formats the table as YAML'], correctAnswer: 1, explanation: 'EXPLAIN supports TEXT (default), JSON, YAML, and XML output formats. JSON and YAML are useful for programmatic analysis of query plans.', tags: ['explain', 'format', 'yaml'] },
  { id: 'pg-idx-l1-086', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What tool visualizes PostgreSQL EXPLAIN output?', options: ['pgAdmin only', 'explain.dalibo.com, pgMustard, or pgAdmin\'s graphical explain', 'No tools exist', 'psql only'], correctAnswer: 1, explanation: 'Several tools visualize EXPLAIN output: explain.dalibo.com (free web tool), pgMustard, and pgAdmin\'s built-in graphical explain view. They make complex plans easier to understand.', tags: ['explain-visualization', 'tools', 'dalibo'] },
  { id: 'pg-idx-l1-087', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the effective_cache_size setting?', options: ['The actual cache size', 'A hint to the planner about how much memory is available for caching (OS cache + shared_buffers), affecting index scan cost estimates', 'The maximum cache allowed', 'Cache expiry time'], correctAnswer: 1, explanation: 'effective_cache_size tells the planner how much data is likely cached. Higher values make index scans appear cheaper (less random I/O). Typically set to 50-75% of total system RAM.', tags: ['effective-cache-size', 'planner-hint', 'io-cost'] },
  { id: 'pg-idx-l1-088', language: 'postgresql', level: 'level1', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is pg_stat_statements and why is it useful for performance?', options: ['A PostgreSQL extension that logs all SQL', 'An extension that tracks query statistics (execution count, time, rows) for identifying slow queries', 'A statement validator', 'A query formatter'], correctAnswer: 1, explanation: 'pg_stat_statements aggregates statistics for distinct query patterns. It shows total/mean execution time, call count, and rows. Essential for finding the queries worth optimizing.', codeSnippet: 'SELECT query, calls, mean_exec_time,\n  total_exec_time\nFROM pg_stat_statements\nORDER BY total_exec_time DESC\nLIMIT 10;', tags: ['pg-stat-statements', 'monitoring', 'slow-queries'] },
];

export default questions;
